<div class="topbar"><h1>Documents</h1></div>
<form class="panel row" method="post" enctype="multipart/form-data" action="/portal/documents/upload"><?= App\Csrf::field() ?><input type="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.webp,.gif,.txt,.csv,.docx,.xlsx,.pptx">
  <select name="project_id" style="max-width:260px"><option value="">Not linked to a project</option><?php foreach ($projects as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['title']) ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">Upload</button><span class="hint">PDF, images, Office files, TXT/CSV · max 10 MB</span></form>
<?php if (!$docs): ?><div class="empty">No documents yet. Certificates, deliverables and receipts will appear here.</div><?php else: ?>
<div class="table-wrap"><table><thead><tr><th>File</th><th>Type</th><th>Project</th><th>Added</th></tr></thead><tbody><?php foreach ($docs as $d): ?><tr><td><a href="/documents/<?= (int)$d['id'] ?>"><?= e($d['filename']) ?></a></td><td><?= e(label($d['kind'])) ?></td><td><?= e($d['project_number'] ?? '—') ?></td><td><?= e(substr($d['created_at'], 0, 10)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
